ALTER TABLE public."Chat_Agents"
    ADD COLUMN IF NOT EXISTS prompts TEXT,
    ADD COLUMN IF NOT EXISTS file_name JSONB DEFAULT '[]',
    ADD COLUMN IF NOT EXISTS urls JSONB DEFAULT '[]',
    ADD COLUMN IF NOT EXISTS raw_text TEXT DEFAULT '',
    ADD COLUMN IF NOT EXISTS total_tokens INT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS total_chunks INT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS file_word_count JSONB DEFAULT '{}',
    ADD COLUMN IF NOT EXISTS url_word_count JSONB DEFAULT '{}',
    ADD COLUMN IF NOT EXISTS raw_text_word_count INT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS actions JSONB DEFAULT '[]';

INSERT INTO public."Chat_Agents" (
    id, created_at, profile_id, bot_name, description,
    workspace_id, color_code, greeting, theme, logo_file_name,
    prompts, file_name, urls, raw_text,
    total_tokens, total_chunks, file_word_count, url_word_count,
    raw_text_word_count, actions
)
VALUES (
    '1dbbac5a-f730-40e0-8fb8-aafd0efa5a16',
    '2026-01-28 07:33:05.168683+00',
    '1ad5123f-9edf-4b97-a86e-7fd2d0812a66',
    'Medicare',
    'You are assistant working for hospital. You are friendly and care for the patients as well as the employees like nurse, doctors and managers.',
    '546edc6f-a4c0-4d74-a040-0a3003e675d4',
    '#800080',
    'Hi! how can I help you?',
    '#ffffff',
    NULL,
    E'Role:\r\nYou are a Hospital Procurement Assistant for a Medicare hospital. Help employees create purchase requests in a polite, professional manner.\r\n\r\nInstructions:\r\n- When a user says they want or need a specific product (e.g. "I want a laptop", "I need a dell laptop"), proceed directly with the purchase request \u2014 product search happens automatically. Only use product search when browsing without purchase intent.\r\n- When a user asks to browse or see what''s available, show product categories.\r\n- Guide the conversation towards completing a purchase request \u2014 collect product selection, quantity, and specifications.\r\n- Keep responses short, natural, and action-oriented. Never mention internal logic or tool names.\r\n\r\nTone: Calm, friendly, professional.',
    '[]'::jsonb,
    '[]'::jsonb,
    '',
    0,
    0,
    '{}'::jsonb,
    '{}'::jsonb,
    1,
    '[
      {
        "id": "act-browse-categories",
        "action_type": "send_api_request",
        "action_name": "Browse Product Categories",
        "instructions": "Fetch available product categories. Use ONLY when user asks to browse products, see what''s available, asks ''what can I order'', or ''show me categories''. NOT needed for direct purchase requests like ''I want a laptop''.",
        "depends_on": [],
        "required_params": [],
        "data": {
          "end_point": "http://127.0.0.1:5000/public/requests/1dbbac5a-f730-40e0-8fb8-aafd0efa5a16/products/categories",
          "api_method": "GET",
          "request_data_type": "json",
          "request_data": [],
          "http_headers": [],
          "output_key": "categories"
        }
      },
      {
        "id": "ad56f29a-d486-413c-983f-c70850fa915c",
        "action_type": "send_api_request",
        "action_name": "Get Products",
        "instructions": "Fetch products for browsing only. Use when user picks a category or wants to explore options WITHOUT purchase intent. Do NOT use when user says ''I want'', ''I need'', or ''get me'' a specific product — that''s a Purchase Request. Pass ''search'' with the product TYPE only (not brand/model). Pass ''category'' when user picks from Browse Product Categories. Both params are optional.",
        "depends_on": [],
        "required_params": [
          {"key": "search", "description": "Product name or keyword from user message (e.g. laptop, printer, bed, ac)", "dynamic": "true", "required": false, "in": "query"},
          {"key": "category", "description": "Category name from categories list (e.g. IT, HVAC, Medical - Imaging)", "dynamic": "true", "required": false, "in": "query"}
        ],
        "data": {
          "end_point": "http://127.0.0.1:5000/public/requests/1dbbac5a-f730-40e0-8fb8-aafd0efa5a16/products",
          "api_method": "GET",
          "request_data_type": "json",
          "request_data": [],
          "http_headers": [],
          "output_key": "products"
        }
      },
      {
        "id": "1b49bb13-2c46-4996-94fa-fd29f0cbf217",
        "action_type": "create_ticket",
        "action_name": "Purchase Request",
        "instructions": "Use when user wants to buy, purchase, or mentions a specific product with intent (e.g. ''I want a laptop'', ''I need a dell laptop'', ''get me laparoscopic equipment''). Product search happens automatically — do NOT use Get Products first.",
        "depends_on": ["ad56f29a-d486-413c-983f-c70850fa915c"],
        "required_params": [
          {"key": "product_id", "description": "Product ID from products list (use id from fetch_products result)", "dynamic": "true", "extractable_from_dep": true, "in": "body"},
          {"key": "quantity", "description": "Quantity to purchase", "dynamic": "true", "value": 1, "in": "body"},
          {"key": "email", "description": "User email address", "dynamic": "true", "in": "body"},
          {"key": "specs", "description": "Product specifications", "dynamic": "true", "value_type": "object", "fields_from_product": true}
        ],
        "data": {
          "request_type": "approval",
          "category": "finance",
          "payload_schema": {
            "data_fields": ["product_id", "quantity", "specs"]
          }
        }
      }
    ]'::jsonb
)
ON CONFLICT (id) DO NOTHING;

